	if body == nil {
		return false, errors.New("nil block body")
	}
	if body.Version() >= version.Capella {
		return true, nil
	}
	payload, err := body.Execution()
	switch {
	case errors.Is(err, consensus_types.ErrUnsupportedField):
		return false, nil
	case err != nil:
